<?php
 namespace Pterodactyl\Services\Dezerx\Rust; use Throwable; use DateTimeZone; use Carbon\CarbonImmutable; use Pterodactyl\Models\Server; use Pterodactyl\Models\EggVariable; use Pterodactyl\Facades\Activity; use Pterodactyl\Models\ServerVariable; use Pterodactyl\Services\Dezerx\Demo; use Pterodactyl\Services\Dezerx\Addons; use Pterodactyl\Models\Dezerx\RustWipe; use Pterodactyl\Models\Dezerx\RustWipeRun; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; class RustWipes { public const TYPES = ['map', 'blueprints', 'full']; public const FREQUENCIES = ['once', 'weekly', 'biweekly', 'monthly']; public const WARNING_STEPS = [60, 30, 15, 10, 5, 1]; public const DEFAULT_MESSAGE = 'The server wipes in {time}.'; public const MAX_SCHEDULES = 10; public const MAX_EXTRA_FILES = 25; public const MAX_SEEDS = 50; public const MAX_SEED = 2147483647; public const MIN_SIZE = 1000; public const MAX_SIZE = 6000; private const LATE_LIMIT = 3600; private const STOP_GRACE = 300; private const STOP_LIMIT = 600; private const STOP_POLL = 45; private const UNREACHABLE_LIMIT = 1800; private const MAP_FILE = '/^(.+\.map|.+\.sav(\.[A-Za-z0-9]+)?|sv\.files(\.\d+)?\.db(-[a-z]+)?|player\.states(\.\d+)?\.db(-[a-z]+)?)$/i'; private const BLUEPRINT_FILE = '/^player\.blueprints(\.\d+)?\.db(-[a-z]+)?$/i'; private const PLAYER_FILE = '/^player\.[a-z]+(\.\d+)?\.db(-[a-z]+)?$/i'; private const EXTRA_PATH = '/^[A-Za-z0-9 _.\-]+(\/[A-Za-z0-9 _.\-]+)*$/'; public function nextOccurrence(RustWipe $wipe, int $after): ?int { try { $zone = new DateTimeZone($wipe->timezone); } catch (Throwable) { return null; } [$hour, $minute] = array_map('intval', explode(':', $wipe->at_time) + [1 => 0]); $at = fn (CarbonImmutable $day) => $day->setTime($hour, $minute)->getTimestamp(); $from = CarbonImmutable::createFromTimestamp($after, $zone)->startOfDay(); switch ($wipe->frequency) { case 'once': $when = $this->startDay($wipe, $zone); return $when && $at($when) > $after ? $at($when) : null; case 'weekly': for ($i = 0; $i <= 8; $i++) { $day = $from->addDays($i); if ($day->dayOfWeek === $wipe->weekday && $at($day) > $after) { return $at($day); } } return null; case 'biweekly': $anchor = $this->startDay($wipe, $zone); if ($anchor === null) { return null; } if ($at($anchor) > $after) { return $at($anchor); } $fortnights = max(0, intdiv(intdiv($from->getTimestamp() - $anchor->getTimestamp(), 86400), 14) - 1); for ($i = $fortnights; $i <= $fortnights + 3; $i++) { $day = $anchor->addDays(14 * $i); if ($at($day) > $after) { return $at($day); } } return null; case 'monthly': for ($i = 0; $i <= 2; $i++) { $day = $from->startOfMonth()->addMonthsNoOverflow($i); while ($day->dayOfWeek !== $wipe->weekday) { $day = $day->addDay(); } if ($at($day) > $after) { return $at($day); } } return null; } return null; } private function startDay(RustWipe $wipe, DateTimeZone $zone): ?CarbonImmutable { if (!is_string($wipe->starts_on) || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $wipe->starts_on)) { return null; } try { return CarbonImmutable::createFromFormat('!Y-m-d', $wipe->starts_on, $zone); } catch (Throwable) { return null; } } public function identity(Server $server): string { $identity = 'rust'; if (preg_match('/\+server\.identity\s+\\\\?["\']?(\{\{\s*[A-Za-z0-9_.]+\s*\}\}|[A-Za-z0-9_.\-]+)/', (string) $server->startup, $match)) { $identity = $match[1]; if (str_starts_with($identity, '{{')) { $name = trim(preg_replace('/^env\./', '', trim($identity, '{} ')) ?? ''); $identity = (string) ($this->variable($server, $name)?->server_value ?? ''); } } return preg_match('/^[A-Za-z0-9_\-]{1,64}$/', $identity) === 1 ? $identity : 'rust'; } public function directory(Server $server): string { return '/server/' . $this->identity($server); } public function variable(Server $server, string $name): ?EggVariable { return $server->variables()->where('env_variable', $name)->first(); } public function classify(string $name): ?string { return match (true) { preg_match(self::BLUEPRINT_FILE, $name) === 1 => 'blueprints', preg_match(self::MAP_FILE, $name) === 1 => 'map', preg_match(self::PLAYER_FILE, $name) === 1 => 'players', default => null, }; } public function buckets(string $type): array { return match ($type) { 'full' => ['map', 'blueprints', 'players'], 'blueprints' => ['map', 'blueprints'], default => ['map'], }; } public function extraPath(mixed $path): ?string { if (!is_string($path)) { return null; } $path = trim(str_replace('\\', '/', $path)); $path = trim(preg_replace('#/+#', '/', preg_replace('#^(\./)+#', '', $path) ?? '') ?? '', '/'); if ($path === '' || mb_strlen($path) > 200 || preg_match(self::EXTRA_PATH, $path) !== 1) { return null; } foreach (explode('/', $path) as $segment) { if (trim($segment) === '' || trim($segment, '.') === '') { return null; } } return $path; } public function chatText(mixed $value, int $max = 120): string { $text = is_scalar($value) ? (string) $value : ''; $text = preg_replace('/[\x00-\x1F\x7F]+/u', ' ', $text) ?? ''; $text = str_replace(['"', '\\', ';'], ["'", '/', ','], $text); return mb_substr(trim(preg_replace('/\s+/u', ' ', $text) ?? ''), 0, $max); } public function arm(int $now): int { $armed = 0; $lead = max(self::WARNING_STEPS) * 60; $due = RustWipe::query() ->where('enabled', true) ->whereNotNull('next_run_at') ->where('next_run_at', '<=', $now + $lead) ->with('server') ->orderBy('next_run_at') ->get(); foreach ($due as $wipe) { $config = $this->config($wipe->config); $warnings = $config['warnings']; $start = $wipe->next_run_at - ($warnings === [] ? 0 : max($warnings) * 60); if ($start > $now) { continue; } $server = $wipe->server; $when = $wipe->next_run_at; $wipe->forceFill([ 'last_run_at' => $when, 'next_run_at' => $this->nextOccurrence($wipe, max($when, $now)), ])->save(); if (!$server instanceof Server || !Addons::appliesTo(Addons::RUST_WIPE_SCHEDULER, $server)) { continue; } if (Demo::is($server->user)) { continue; } $run = new RustWipeRun([ 'server_id' => $server->id, 'wipe_id' => $wipe->id, 'name' => $wipe->name, 'trigger' => 'schedule', 'status' => RustWipeRun::PENDING, 'settings' => $config, 'scheduled_for' => $when, 'warned' => [], 'user_id' => $wipe->created_by, ]); if ($now - $when > self::LATE_LIMIT) { $run->forceFill([ 'status' => RustWipeRun::MISSED, 'error' => 'The panel was not running when this wipe was due, so it was skipped rather than run late.', 'finished_at' => $now, ]); } elseif ($this->activeRun($server) !== null) { $run->forceFill([ 'status' => RustWipeRun::MISSED, 'error' => 'Another wipe was still running on this server.', 'finished_at' => $now, ]); } else { $armed++; } $run->save(); } return $armed; } public function activeRun(Server $server): ?RustWipeRun { return RustWipeRun::query() ->where('server_id', $server->id) ->whereIn('status', RustWipeRun::ACTIVE) ->orderBy('id') ->first(); } public function active() { return RustWipeRun::query()->whereIn('status', RustWipeRun::ACTIVE)->with('server')->orderBy('scheduled_for')->get(); } public function advance(RustWipeRun $run, int $now): void { $server = $run->server; if (!$server instanceof Server) { $this->finish($run, RustWipeRun::CANCELLED, 'The server no longer exists.'); return; } $files = new ServerFiles($server); try { if ($run->status === RustWipeRun::PENDING) { if ($run->scheduled_for > $now) { $this->warn($run, $files, $now); return; } if (!$this->begin($run, $server, $files, $now)) { return; } } if ($run->status === RustWipeRun::STOPPING && !$this->awaitStop($run, $files)) { return; } if ($run->status === RustWipeRun::WIPING) { $this->wipe($run, $server, $files); } if ($run->status === RustWipeRun::STARTING) { $this->start($run, $files); } } catch (Throwable $exception) { report($exception); $this->fail($run, $files, 'Something went wrong: ' . mb_substr($exception->getMessage(), 0, 300)); } } private function warn(RustWipeRun $run, ServerFiles $files, int $now): void { $left = $run->scheduled_for - $now; $warned = array_map('intval', $run->warned ?? []); $due = array_values(array_filter( $run->settings['warnings'] ?? [], fn ($minutes) => !in_array((int) $minutes, $warned, true) && $left <= (int) $minutes * 60 + 30, )); if ($due === []) { return; } $closest = min(array_map('intval', $due)); if ($files->powerStateOrNull() === 'running') { $template = (string) ($run->settings['message'] ?? '') ?: self::DEFAULT_MESSAGE; $text = $this->chatText(str_replace('{time}', $this->duration($closest), $template)); if ($text !== '') { $files->sendCommand('say "' . $text . '"'); } } $run->forceFill(['warned' => array_values(array_unique([...$warned, ...array_map('intval', $due)]))])->save(); } private function duration(int $minutes): string { if ($minutes >= 60 && $minutes % 60 === 0) { $hours = intdiv($minutes, 60); return $hours === 1 ? '1 hour' : "{$hours} hours"; } return $minutes === 1 ? '1 minute' : "{$minutes} minutes"; } private function begin(RustWipeRun $run, Server $server, ServerFiles $files, int $now): bool { $server->refresh(); if (!Addons::appliesTo(Addons::RUST_WIPE_SCHEDULER, $server)) { $this->finish($run, RustWipeRun::CANCELLED, 'The Wipe Scheduler is turned off for this server.'); return false; } try { $server->validateCurrentState(); } catch (Throwable) { $this->finish($run, RustWipeRun::FAILED, 'The server is suspended, installing, restoring a backup or being transferred, so nothing was wiped.'); return false; } $state = $files->powerStateOrNull(); if ($state === null) { if ($now - $run->scheduled_for > self::UNREACHABLE_LIMIT) { $this->finish($run, RustWipeRun::FAILED, 'The node could not be reached, so nothing was wiped.'); } return false; } $claimed = RustWipeRun::query() ->whereKey($run->id) ->where('status', RustWipeRun::PENDING) ->update(['status' => RustWipeRun::STOPPING, 'started_at' => $now, 'updated_at' => now()]); if ($claimed === 0) { return false; } $running = $state !== 'offline'; $run->forceFill(['status' => RustWipeRun::STOPPING, 'started_at' => $now, 'was_running' => $running]); if (!$running) { $run->forceFill(['status' => RustWipeRun::WIPING])->save(); return true; } if ($state === 'running') { $files->sendCommand('say "The server is wiping now and will be back shortly."'); } if (!$files->setPower('stop')) { $this->finish($run, RustWipeRun::FAILED, 'The node would not stop the server, so nothing was wiped.'); return false; } $run->forceFill(['stop_sent_at' => time()])->save(); return true; } private function awaitStop(RustWipeRun $run, ServerFiles $files): bool { $until = time() + self::STOP_POLL; do { if ($files->powerStateOrNull() === 'offline') { $run->forceFill(['status' => RustWipeRun::WIPING])->save(); return true; } $waited = time() - (int) $run->stop_sent_at; if ($waited >= self::STOP_LIMIT) { $this->finish($run, RustWipeRun::FAILED, 'The server did not stop within ten minutes, so nothing was wiped.'); return false; } if ($waited >= self::STOP_GRACE && !$run->killed) { $files->setPower('kill'); $run->forceFill(['killed' => true])->save(); } sleep(3); } while (time() < $until); return false; } private function wipe(RustWipeRun $run, Server $server, ServerFiles $files): void { $settings = $this->config($run->settings); $directory = $this->directory($server); $entries = $files->listFiles($directory); if ($entries === null && $files->powerStateOrNull() === null) { $this->fail($run, $files, "The node could not list {$directory}, so nothing was wiped."); return; } $buckets = $this->buckets($settings['type']); $doomed = []; foreach ($entries ?? [] as $entry) { if (!$entry['directory'] && in_array($this->classify($entry['name']), $buckets, true)) { $doomed[] = $entry['name']; } } if ($doomed !== [] && !$files->deletePaths($directory, $doomed)) { $this->fail($run, $files, "The node would not delete the save files in {$directory}, so the map was not wiped."); return; } $deleted = array_map(fn ($name) => ltrim($directory, '/') . '/' . $name, $doomed); $skipped = []; $byFolder = []; foreach ($settings['extraFiles'] as $path) { $folder = str_contains($path, '/') ? '/' . dirname($path) : '/'; $byFolder[$folder][] = basename($path); } foreach ($byFolder as $folder => $names) { $present = array_column($files->listFiles($folder) ?? [], 'name'); $found = array_values(array_intersect(array_unique($names), $present)); if ($found === []) { continue; } if ($files->deletePaths($folder, $found)) { foreach ($found as $name) { $deleted[] = ltrim(rtrim($folder, '/') . '/' . $name, '/'); } } else { $skipped[] = ltrim($folder, '/'); } } $seed = $this->changeSeed($server, $settings); $run->forceFill([ 'status' => RustWipeRun::STARTING, 'deleted' => array_slice($deleted, 0, 200), 'seed' => $seed, 'error' => $skipped === [] ? null : 'Some extra files could not be deleted in: ' . implode(', ', $skipped), ])->save(); } private function changeSeed(Server $server, array $settings): ?string { $seedVariable = $this->variable($server, 'WORLD_SEED'); $seed = null; if ($seedVariable !== null && $seedVariable->user_editable) { $current = (string) ($seedVariable->server_value ?? ''); if ($settings['seedMode'] === 'random') { $seed = (string) random_int(1, self::MAX_SEED); } elseif ($settings['seedMode'] === 'list' && $settings['seeds'] !== []) { $seeds = $settings['seeds']; $at = array_search($current, $seeds, true); $seed = $at === false ? $seeds[0] : $seeds[($at + 1) % count($seeds)]; } if ($seed !== null) { $this->setVariable($server, $seedVariable, $seed); } } $sizeVariable = $this->variable($server, 'WORLD_SIZE'); if ($settings['worldSize'] !== null && $sizeVariable !== null && $sizeVariable->user_editable) { $this->setVariable($server, $sizeVariable, (string) $settings['worldSize']); } return $seed; } private function setVariable(Server $server, EggVariable $variable, string $value): void { ServerVariable::query()->updateOrCreate( ['server_id' => $server->id, 'variable_id' => $variable->id], ['variable_value' => $value], ); } private function start(RustWipeRun $run, ServerFiles $files): void { $settings = $this->config($run->settings); if ($settings['startAfter'] && $run->was_running && !$files->setPower('start')) { $this->finish($run, RustWipeRun::FAILED, 'The server was wiped, but the node would not start it again.'); return; } $this->finish($run, RustWipeRun::DONE, $run->error); } private function fail(RustWipeRun $run, ServerFiles $files, string $error): void { if ($run->was_running && in_array($run->status, [RustWipeRun::STOPPING, RustWipeRun::WIPING, RustWipeRun::STARTING], true)) { if ($files->setPower('start')) { $error .= ' The server was started again.'; } } $this->finish($run, RustWipeRun::FAILED, $error); } private function finish(RustWipeRun $run, string $status, ?string $error): void { $run->forceFill(['status' => $status, 'error' => $error, 'finished_at' => time()])->save(); if ($run->server instanceof Server && in_array($status, [RustWipeRun::DONE, RustWipeRun::FAILED], true)) { Activity::event($status === RustWipeRun::DONE ? 'server:rust-wipe.complete' : 'server:rust-wipe.fail') ->subject($run->server) ->property([ 'name' => $run->name, 'type' => $run->settings['type'] ?? 'map', 'files' => count($run->deleted ?? []), 'seed' => $run->seed, 'error' => $status === RustWipeRun::FAILED ? $error : null, ]) ->log(); } } public function config(mixed $config): array { $config = is_array($config) ? $config : []; $warnings = array_values(array_unique(array_filter( array_map('intval', is_array($config['warnings'] ?? null) ? $config['warnings'] : []), fn (int $minutes) => in_array($minutes, self::WARNING_STEPS, true), ))); rsort($warnings); $seeds = []; foreach (is_array($config['seeds'] ?? null) ? $config['seeds'] : [] as $seed) { $seed = trim((string) (is_scalar($seed) ? $seed : '')); if (preg_match('/^\d{1,10}$/', $seed) === 1 && (int) $seed >= 1 && (int) $seed <= self::MAX_SEED) { $seeds[] = (string) (int) $seed; } } $extra = []; foreach (is_array($config['extraFiles'] ?? null) ? $config['extraFiles'] : [] as $path) { if (($path = $this->extraPath($path)) !== null) { $extra[] = $path; } } $size = $config['worldSize'] ?? null; $size = is_numeric($size) && (int) $size >= self::MIN_SIZE && (int) $size <= self::MAX_SIZE ? (int) $size : null; $type = in_array($config['type'] ?? null, self::TYPES, true) ? $config['type'] : 'map'; $seedMode = in_array($config['seedMode'] ?? null, ['keep', 'random', 'list'], true) ? $config['seedMode'] : 'keep'; return [ 'type' => $type, 'warnings' => $warnings, 'message' => $this->chatText($config['message'] ?? '') ?: self::DEFAULT_MESSAGE, 'seedMode' => $seedMode === 'list' && $seeds === [] ? 'keep' : $seedMode, 'seeds' => array_slice(array_values(array_unique($seeds)), 0, self::MAX_SEEDS), 'worldSize' => $size, 'extraFiles' => array_slice(array_values(array_unique($extra)), 0, self::MAX_EXTRA_FILES), 'startAfter' => (bool) ($config['startAfter'] ?? true), ]; } } 